INSERT OR REPLACE INTO lab_topics (id, chapter_id, title, content, created_at) VALUES 
('t21', 'chap-03', 'What Exactly is a Zero-Day?', 'A Zero-Day vulnerability is an undiscovered software flaw known only to the attacker. The term "zero-day" refers to the fact that developers have had zero days to create a patch. When threat actors discover these flaws, they secretly develop weaponized exploits to breach networks, operating entirely undetected because antivirus engines lack the signature to recognize the incoming attack.', 1711750000),
('t22', 'chap-03', 'The Underground Zero-Day Market', 'Zero-Day exploits are highly lucrative global commodities. State-sponsored hackers and cyber mercenaries routinely purchase these vulnerabilities for millions of dollars on Dark Web forums or through institutionalized brokers. Advanced exploits targeting iOS or major enterprise firewalls can demand staggering payouts, incentivizing researchers to sell exclusively to cartels rather than responsibly disclosing them to vendors.', 1711750001),
('t23', 'chap-03', 'Exploit Chains & Escalation', 'A single Zero-Day is rarely sufficient for a full breach. Attackers string multiple vulnerabilities together into an "Exploit Chain". An initial browser Zero-Day might grant limited Execution access, which is immediately chained to an OS-level Zero-Day for Privilege Escalation, ultimately granting the threat actor unchecked, root-level administrative access to the entire host infrastructure.', 1711750002),
('t24', 'chap-03', 'Detection: Heuristic Analysis', 'Because Zero-Days lack known signatures, traditional Antivirus is completely blind to them. Defense relies on Endpoint Detection and Response platforms utilizing Heuristic and Behavioral Analysis. Instead of looking for a known malware file, EDR monitors for highly anomalous behaviors—such as a word processor unexpectedly spawning an unrecognized PowerShell script mapping the external network.', 1711750003),
('t25', 'chap-03', 'Bug Bounty Programs', 'To combat the illicit marketplace, technology giants deploy proactive Bug Bounty Programs. Organizations offer substantial financial incentives, sometimes reaching millions of dollars, rewarding "White Hat" ethical hackers who responsibly report critical Zero-Days before they can be weaponized. This fundamentally shifts the economic incentive towards securing the software pipeline rather than exploiting it.', 1711750004),
('t26', 'chap-03', 'The Window of Exposure', 'The time between a vendor publicly acknowledging a vulnerability and the organization successfully applying the patch is called the Window of Exposure. Cybercriminal cartels aggressively monitor vendor patch notes, immediately reverse-engineering the fixes to develop "1-Day" exploits. Exploiting enterprise lag, they ravage thousands of unpatched servers globally before IT teams can deploy the updates.', 1711750005),
('t27', 'chap-03', 'Stuxnet: The Ultimate Zero-Day Weapon', 'Stuxnet, discovered in 2010, fundamentally altered modern cyberwarfare. Engineered aggressively by nation-states, it explicitly utilized an unprecedented four simultaneous Zero-Day vulnerabilities to bypass Windows security architectures. It targeted Iranian nuclear enrichment facilities, stealthily bridging the air-gapped network via infected USB drives, ultimately commanding the industrial centrifuges to physically tear themselves apart while reporting normal operations.', 1711750006),
('t28', 'chap-03', 'Defending Air-Gapped Networks', 'Air-gapping—physically severing a computer from the internet—is the ultimate defense against remote Zero-Days. However, attackers bridge these gaps utilizing compromised human proxies. They execute localized social engineering drops, leaving malware-laced USB flash drives near the target facility, relying entirely on an unsuspecting employee to manually insert the payload perfectly behind the unreachable physical perimeter.', 1711750007),
('t29', 'chap-03', 'Zero-Day Architectural Defense', 'Since organizations cannot actively prevent a Zero-Day compromise, survival depends strictly on architectural containment. By implementing Zero Trust network micro-segmentation, if an attacker executes a zero-day payload on a compromised HR workstation, they run into isolated lateral firewalls physically preventing them from bridging their localized access over to the highly-secured Engineering or Financial subnets.', 1711750008),
('t30', 'chap-03', 'Incident Response Under Fire', 'When an undiscovered Zero-Day breach is finally identified, chaos ensues. Incident Responders must operate under strict assumption of a fully compromised internal environment. Rapid remediation requires severing external internet access, capturing raw RAM memory dumps for behavioral forensics, and implementing aggressive, out-of-band communication channels since the corporate email infrastructure is fundamentally untrustworthy.', 1711750009),

('t31', 'chap-04', 'What You Know, Have, and Are', 'Multi-Factor Authentication disrupts brute-force attacks by requiring credentials from two or more distinct categories. These categories are: Something you Know (a complex password), Something you Have (a smartphone or hardware token), and Something you Are (biological fingerprint or retina scan). Relying on just a password leaves an organization one data breach away from catastrophic compromise.', 1711750010),
('t32', 'chap-04', 'SMS OTP Vulnerabilities', 'Using SMS for MFA codes is notoriously insecure due to SIM Swapping attacks. Threat actors call mobile carriers, impersonating the victim, and successfully port the target phone number to an attacker-controlled SIM card. They immediately intercept all incoming 6-digit text messages in real-time, effortlessly bypassing the primary MFA security layer entirely from thousands of miles away.', 1711750011),
('t33', 'chap-04', 'Time-Based One-Time Passwords', 'TOTP apps like Google Authenticator drastically improve security over SMS. A unified cryptographic seed is securely exchanged mathematically between your device and the server via a QR code. Both the phone and server use the identical algorithm to generate a matching 6-digit code that predictably cycles every 30 seconds entirely offline, isolating the token from telecom interceptions.', 1711750012),
('t34', 'chap-04', 'Hardware Security Keys (FIDO2)', 'Hardware security keys, such as YubiKeys, represent the absolute zenith of modern MFA authentication. Utilizing FIDO2 configurations, these physical USB or NFC devices rely upon complex asymmetric cryptography. Because the private key mathematically never leaves the physical hardware token, it is completely immune to traditional phishing, credential stuffing, and remote brute-force account takeovers.', 1711750013),
('t35', 'chap-04', 'Biometrics & Liveness Spoofing', 'Biometrics offer high-friction security but suffer from one fatal flaw: they cannot be easily rotated if stolen. As fingerprints and facial data are increasingly harvested by threat actors, biometric scanners must combat sophisticated spoofing. Attackers utilize high-definition 3D-printed masks or synthetic Deepfake video streams to trick sensors. Defensive algorithms increasingly verify "liveness", measuring micro-dilations in the eye.', 1711750014),
('t36', 'chap-04', 'The Danger of MFA Fatigue', 'MFA Fatigue is a psychological attack where threat actors spam thousands of rapid-fire administrative approval notifications to a victim''s smartphone continuously throughout the night. Worn down by the overwhelming alert bombardment and trying to silence their phone to sleep, the victim inadvertently taps "Approve", accidentally granting the cybercriminals unchecked, authorized passage into the corporate perimeter.', 1711750015),
('t37', 'chap-04', 'Combating Fatigue Bombing', 'To mitigate MFA Fatigue, organizations enforce "Number Matching" algorithms. Instead of a simple Approve/Deny button, the user must look at a two-digit number displayed natively on their compromised laptop screen, and manually type that exact number into their secure mobile authenticator application. This physical cross-verification fundamentally terminates blind, frustrated push-notification approvals.', 1711750016),
('t38', 'chap-04', 'Adversary-in-the-Middle (AiTM)', 'AiTM phishing effectively destroys standard TOTP and SMS authentication methods. Attackers route victims to a real-time proxy server perfectly mirroring the corporate login page. When the victim enters their password and the 6-digit MFA code, the proxy instantly passes it to the legitimate server, actively stealing the resulting authenticated Session Cookie to permanently establish unchecked persistence.', 1711750017),
('t39', 'chap-04', 'Adaptive Authentication Strategies', 'Adaptive Authentication shifts risk evaluation dynamically behind the scenes. Instead of blindly trusting correct MFA inputs, the algorithm analyzes behavioral telemetry. If a user natively logs in from Manhattan, but suddenly connects five minutes later from an IP address block in Moscow, Adaptive systems immediately revoke access and forcefully demand extreme secondary authentication verification regardless of correct credentials.', 1711750018),
('t40', 'chap-04', 'The Future: Passwordless Environments', 'Passkeys and Passwordless architecture aim to eradicate the concept of user-generated passwords entirely. Devices generate unique, mathematically linked cryptographic keypairs for every web service. Authentication happens silently via a biometric gesture on a trusted mobile device, sending solely public key signatures over the wire. This completely destroys the viability of massive, dark web credential harvesting dumps.', 1711750019);
